                $LocalCloudCacheProfileContainerPaths.Add("type=smb,connectionString=\\$($SAFQDN)\$($ProfileShareName)")
                Write-Log -message "LocalCloudCacheProfileContainerPath: 'type=smb,connectionString=\\$($SAFQDN)\$($ProfileShareName)'"
            }
